// ============================================================
// PTS1 Test - Client Script (FINAL)
// ✅ Matches your Server Script routing: uses api_cmd (NOT cmd)
// ✅ Workflow:
//    1) Enter 4 PCB serials -> Save
//    2) Click "Find COM Ports" -> connector fills com_port
//    3) Click Dump/Flash per lane -> sets Requested + saves (connector polls and runs)
//    4) After Flash Done -> Upload (calls pts1_api upload_result_to_master_ledger)
//    5) Enter NEW serial in same lane -> lane auto-clears (keeps COM)
// ✅ Lane Reset (single) + Reset All (keep COM)
// ✅ Safe if find_com_status / find_com_message fields do not exist
// ✅ No duplicate function definitions
// ============================================================

(function () {
  // -----------------------
  // Main hooks
  // -----------------------
  frappe.ui.form.on("PTS1 Test", {
    onload(frm) {
      ensure_four_lanes(frm);
    },

    refresh(frm) {
      ensure_four_lanes(frm);

      setup_auto_reset_on_serial_change(frm);

      render_lane_dashboard(frm);
      sync_lane_logs_to_fields(frm);
      start_auto_refresh_if_needed(frm);

      // keep logs + dashboard updated when child table edits happen
      const grid = frm.fields_dict.lanes?.grid;
      if (grid?.wrapper) {
        grid.wrapper.off("change.pts1logsync");
        grid.wrapper.on("change.pts1logsync", () => {
          sync_lane_logs_to_fields(frm);
          render_lane_dashboard(frm);
          start_auto_refresh_if_needed(frm);
        });
      }

      inject_pts1_css_once();

      // optional helper: show toast when ports assigned
      show_com_scan_result_hint(frm);

      // optional: auto-request COM scan once if any serial exists but COM missing
      auto_request_com_scan_if_needed(frm);

      // add Reset All button (keep COM)
      add_reset_all_button(frm);
    },

    // Button fieldname in DocType = find_com_port
    find_com_port(frm) {
      request_find_com(frm);
    }
  });

  // -----------------------
  // Init 4 lanes
  // -----------------------
  function ensure_four_lanes(frm) {
    const lanes = frm.doc.lanes || [];
    if (lanes.length > 0) return;

    for (let i = 1; i <= 4; i++) {
      const row = frm.add_child("lanes");
      row.lane_no = i;
      row.lane_status = "Pending";
      row.lane_progress = 0;
      row.lane_action = "";
      row.lane_action_status = "";
      row.lane_action_message = "";
      row.lane_step = "";
      row.error_message = "";
      row.com_port = "";
      row.mac_id = "";
      row.lane_log = "";
      row.lane_result_json = "";
    }
    frm.refresh_field("lanes");
  }

  // -----------------------
  // Auto reset lane on serial change (KEEP com_port)
  // -----------------------
  function setup_auto_reset_on_serial_change(frm) {
    if (frm.__pts1_serial_reset_hooked) return;
    frm.__pts1_serial_reset_hooked = true;

    const lanes_field = frm.fields_dict.lanes;
    if (!lanes_field?.df?.options) return;

    const child_dt = lanes_field.df.options;
    if (!window.__pts1_prev_serial_map) window.__pts1_prev_serial_map = {};

    frappe.model.on(child_dt, {
      pcb_serial_no: function (doc, cdt, cdn) {
        if (!frm?.doc) return;
        if (doc.parenttype !== "PTS1 Test") return;
        if (doc.parent !== frm.doc.name) return;

        const new_serial = ((doc.pcb_serial_no || "") + "").trim();
        const key = cdn;
        const old_serial = ((window.__pts1_prev_serial_map[key] || "") + "").trim();

        // first time record only
        if (!old_serial) {
          window.__pts1_prev_serial_map[key] = new_serial;
          return;
        }
        if (new_serial === old_serial) return;

        window.__pts1_prev_serial_map[key] = new_serial;

        // if user cleared serial, don't auto reset
        if (!new_serial) return;

        // ✅ clear ONLY testing state (keep lane_no, com_port, pcb_serial_no)
        const reset_fields = {
          lane_status: "Pending",
          lane_action: "",
          lane_action_status: "",
          lane_action_message: "",
          lane_progress: 0,
          lane_step: "",
          error_message: "",
          lane_log: "",
          mac_id: "",
          lane_result_json: "",
          fw_file: ""
        };

        Object.keys(reset_fields).forEach((k) => {
          frappe.model.set_value(cdt, cdn, k, reset_fields[k]);
        });

        const ln = doc.lane_no || "?";
        frappe.show_alert({ message: `Lane ${ln} cleared (COM kept) for new PCB: ${new_serial}`, indicator: "orange" });

        // debounced autosave (so connector sees clean lane quickly)
        if (frm.__pts1_autosave_timer) clearTimeout(frm.__pts1_autosave_timer);
        frm.__pts1_autosave_timer = setTimeout(() => {
          frm.__pts1_autosave_timer = null;
          if (!frm.is_new() && frm.is_dirty()) frm.save().catch(() => {});
        }, 700);
      }
    });
  }

  // -----------------------
  // Helpers
  // -----------------------
  function normalize(s) {
    return (s || "").toString().trim().toLowerCase();
  }

  function field_exists(frm, fieldname) {
    return !!frm.fields_dict?.[fieldname];
  }

  function isBusy(row) {
    const st = normalize(row?.lane_action_status);
    return st === "requested" || st === "running";
  }

  function isDone(row) {
    return normalize(row?.lane_action_status) === "done";
  }

  function laneCompleted(row) {
    return normalize(row?.lane_status) === "completed";
  }

  function anyLaneActive(frm) {
    return (frm.doc.lanes || []).some((r) => {
      const s = normalize(r.lane_action_status);
      return s === "requested" || s === "running";
    });
  }

  async function set_child_values_and_save(frm, row, values) {
    for (const k of Object.keys(values)) {
      await frappe.model.set_value(row.doctype, row.name, k, values[k]);
    }
    frm.refresh_field("lanes");
    await frm.save();
  }

  function lane_row(frm, lane_no) {
    return (frm.doc.lanes || []).find((r) => Number(r.lane_no) === Number(lane_no));
  }

  // -----------------------
  // Find COM (calls server -> connector updates)
  // -----------------------
  function request_find_com(frm) {
    const st = (frm.doc.find_com_status || "Idle");
    if (st === "Requested" || st === "Running") {
      frappe.msgprint("COM scan already requested. Please wait…");
      return;
    }

    const run = async () => {
      console.log("[PTS1] FIND_COM -> calling pts1_api", { docname: frm.doc.name });

      if (field_exists(frm, "find_com_status")) await frm.set_value("find_com_status", "Requested");
      if (field_exists(frm, "find_com_message")) await frm.set_value("find_com_message", "");

      return frappe
        .call({
          method: "pts1_api",
          args: { api_cmd: "request_find_com", docname: frm.doc.name },
          freeze: true,
          freeze_message: "Requesting COM scan..."
        })
        .then(() => {
          // connector updates ports async; reload after a short delay
          setTimeout(() => frm.reload_doc(), 1200);
        })
        .catch((e) => {
          console.error("[PTS1] request_find_com failed", e);
          frappe.msgprint("Find COM failed. Check server script / connector logs.");
        });
    };

    if (frm.is_new()) frm.save().then(run);
    else run();
  }

  function auto_request_com_scan_if_needed(frm) {
    if (frm.is_new()) return;
    if (frm.__auto_com_requested) return;

    // only if those fields exist (otherwise avoid noise)
    if (!field_exists(frm, "find_com_status")) return;

    const st = (frm.doc.find_com_status || "Idle");
    if (st === "Requested" || st === "Running") return;

    const lanes = frm.doc.lanes || [];
    const anyMissingCom = lanes.some((r) => {
      const sn = (r.pcb_serial_no || "").toString().trim();
      const cp = (r.com_port || "").toString().trim();
      return sn && !cp;
    });
    if (!anyMissingCom) return;

    frm.__auto_com_requested = true;
    console.log("[PTS1] Auto COM scan triggered");
    request_find_com(frm);
  }

  function show_com_scan_result_hint(frm) {
    const st = (frm.doc.find_com_status || "");
    if (st !== "Done") return;

    const ports = (frm.doc.lanes || []).map((r) => r.com_port).filter(Boolean);
    if (!ports.length) return;

    const sig = ports.join(",");
    if (frm.__last_com_sig === sig) return;
    frm.__last_com_sig = sig;

    frappe.show_alert({ message: `COM Assigned: ${sig}`, indicator: "green" });
  }

  // -----------------------
  // Actions: Dump / Flash (write Requested + Save)
  // -----------------------
  async function request_action(frm, lane_no, action) {
    if (frm.is_new()) return frappe.msgprint("Please click Save first, then press Dump/Flash.");

    const row = lane_row(frm, lane_no);
    if (!row) return frappe.msgprint(`Lane ${lane_no} row not found.`);

    const sn = (row.pcb_serial_no || "").toString().trim();
    const cp = (row.com_port || "").toString().trim();
    if (!sn || !cp) return frappe.msgprint(`Lane ${lane_no}: PCB Serial No and COM Port are required.`);

    if (isBusy(row)) return frappe.msgprint(`Lane ${lane_no} is already ${row.lane_action_status}.`);

    console.log("[PTS1] SET Requested + SAVE", { lane_no, action });

    await set_child_values_and_save(frm, row, {
      lane_action: action,
      lane_action_status: "Requested",
      lane_status: "Queued",
      lane_progress: 0,
      lane_action_message: "Requested " + action,
      error_message: "",
      lane_log: "" // clear old log for new run
    });

    await frm.reload_doc();
    frappe.show_alert({ message: `Lane ${lane_no} queued for ${action}`, indicator: "blue" });
  }

  // -----------------------
  // Upload (calls pts1_api)
  // -----------------------
  async function upload_lane_result(frm, lane_no) {
    if (frm.is_new()) return frappe.msgprint("Please click Save first.");

    const row = lane_row(frm, lane_no);
    if (!row) return frappe.msgprint(`Lane ${lane_no} row not found.`);

    const sn = (row.pcb_serial_no || "").toString().trim();
    if (!sn) return frappe.msgprint(`Lane ${lane_no}: PCB Serial No is required.`);

    if (!isDone(row)) {
      return frappe.msgprint(`Lane ${lane_no}: Run Flash first. Lane Action Status is "${row.lane_action_status || ""}".`);
    }

    // OPTIONAL (strong gating): only allow upload if lane_status is Completed
    // If you want upload even when Failed, comment this block.
    // if (!laneCompleted(row)) {
    //   return frappe.msgprint(`Lane ${lane_no}: Test is not Completed. Lane Status is "${row.lane_status || ""}".`);
    // }

    console.log("[PTS1] CALL pts1_api upload_result_to_master_ledger", { docname: frm.doc.name, lane_no });

    return frappe
      .call({
        method: "pts1_api",
        args: {
          api_cmd: "upload_result_to_master_ledger",
          pts1_docname: frm.doc.name,
          lane_no: lane_no
        },
        freeze: true,
        freeze_message: `Uploading Lane ${lane_no} result...`
      })
      .then(() => frm.reload_doc())
      .catch((e) => {
        console.error("[PTS1] upload failed", e);
        frappe.msgprint("Upload failed. Check server script / ledger stage / PCB Master existence.");
      });
  }

  // -----------------------
  // Reset Lane (keep COM + keep serial? -> we will CLEAR testing state but KEEP serial+com)
  // If you want serial cleared too, set pcb_serial_no:"" below.
  // -----------------------
  async function reset_lane(frm, lane_no) {
    if (frm.is_new()) return frappe.msgprint("Please click Save first.");

    const row = lane_row(frm, lane_no);
    if (!row) return frappe.msgprint(`Lane ${lane_no} row not found.`);
    if (isBusy(row)) return frappe.msgprint(`Lane ${lane_no} is ${row.lane_action_status}. Stop/Wait before reset.`);

    frappe.confirm(`Reset Lane ${lane_no}? This clears result/log/status (COM kept).`, async () => {
      console.log("[PTS1] RESET lane locally + SAVE", { lane_no });

      await set_child_values_and_save(frm, row, {
        lane_action: "",
        lane_action_status: "",
        lane_status: "Pending",
        lane_progress: 0,
        lane_action_message: "",
        lane_step: "",
        error_message: "",
        mac_id: "",
        lane_log: "",
        lane_result_json: "",
        fw_file: ""
        // pcb_serial_no: ""   // uncomment if you want reset to clear serial too
        // com_port: row.com_port // keep COM automatically (we are not touching it)
      });

      await frm.reload_doc();
      frappe.show_alert({ message: `Lane ${lane_no} reset (COM kept)`, indicator: "orange" });
    });
  }

  // -----------------------
  // Reset All (keep COM) button
  // Clears lane state + serials (you asked: after 4 lanes done -> one reset button -> enter next 4 serials)
  // We WILL clear pcb_serial_no, but keep com_port.
  // -----------------------
  function add_reset_all_button(frm) {
    if (frm.__pts1_reset_all_added) return;
    frm.__pts1_reset_all_added = true;

    // Place a custom button under the form "Actions" menu
    frm.add_custom_button("Reset All (keep COM)", async () => {
      if (frm.is_new()) return frappe.msgprint("Save the document first.");

      // don't allow while any lane running/requested
      if (anyLaneActive(frm)) {
        frappe.msgprint("Some lanes are Running/Requested. Wait until they finish before Reset All.");
        return;
      }

      frappe.confirm("Reset ALL 4 lanes? This clears serials + logs + results, but keeps COM ports.", async () => {
        const lanes = frm.doc.lanes || [];
        for (const r of lanes) {
          await frappe.model.set_value(r.doctype, r.name, "pcb_serial_no", "");
          await frappe.model.set_value(r.doctype, r.name, "lane_action", "");
          await frappe.model.set_value(r.doctype, r.name, "lane_action_status", "");
          await frappe.model.set_value(r.doctype, r.name, "lane_status", "Pending");
          await frappe.model.set_value(r.doctype, r.name, "lane_progress", 0);
          await frappe.model.set_value(r.doctype, r.name, "lane_action_message", "");
          await frappe.model.set_value(r.doctype, r.name, "lane_step", "");
          await frappe.model.set_value(r.doctype, r.name, "error_message", "");
          await frappe.model.set_value(r.doctype, r.name, "lane_log", "");
          await frappe.model.set_value(r.doctype, r.name, "mac_id", "");
          await frappe.model.set_value(r.doctype, r.name, "lane_result_json", "");
          // com_port intentionally untouched
        }

        frm.refresh_field("lanes");
        await frm.save();
        await frm.reload_doc();

        // reset serial tracking map so auto-reset logic doesn't misfire
        window.__pts1_prev_serial_map = {};

        frappe.show_alert({ message: "All lanes reset (COM kept). Enter next 4 PCB serial numbers.", indicator: "green" });
      });
    });
  }

  // -----------------------
  // Dashboard UI
  // -----------------------
  function render_lane_dashboard(frm) {
    const html_field = frm.fields_dict.lane_dashboard;
    if (!html_field) return;

    const wrap = $(html_field.wrapper);
    wrap.empty();

    const $root = $(`<div class="pts1-dash"><div class="pts1-rows"></div></div>`);
    wrap.append($root);

    const $rows = $root.find(".pts1-rows");

    for (let lane = 1; lane <= 4; lane++) {
      const row = lane_row(frm, lane);

      const progress = row ? Number(row.lane_progress || 0) : 0;
      const status = row ? (row.lane_status || "Pending") : "Pending";
      const astatus = row ? (row.lane_action_status || "") : "";
      const amsg = row?.lane_action_message ? ` • ${row.lane_action_message}` : "";
      const err = row?.error_message ? ` • ${row.error_message}` : "";
      const barText = `${status}${astatus ? " • " + astatus : ""}${amsg}${err} (${progress}%)`;

      const barClass =
        normalize(status) === "failed" ? "pts1-barfill-failed" :
        normalize(status) === "completed" ? "pts1-barfill-done" :
        normalize(status) === "running" ? "pts1-barfill-running" :
        normalize(status) === "queued" ? "pts1-barfill-queued" :
        normalize(status) === "aborted" ? "pts1-barfill-aborted" :
        "pts1-barfill-pending";

      const busy = isBusy(row);

      // Button enable rules:
      // - Dump/Flash disabled if busy
      // - Upload enabled only if Done AND lane_status Completed (you said upload on successful flash)
      const uploadEnabled = !!row && isDone(row) && laneCompleted(row) && !busy;

      const $laneRow = $(`
        <div class="pts1-row">
          <div class="pts1-label">L${lane}</div>

          <div class="pts1-bar">
            <div class="pts1-barfill ${barClass}" style="width:${Math.max(0, Math.min(100, progress))}%"></div>
            <div class="pts1-bartext">${frappe.utils.escape_html(barText)}</div>
          </div>

          <div class="pts1-actions">
            <button type="button" class="btn btn-default btn-sm pts1-btn"
              data-action="VERIFY" data-lane="${lane}" ${busy ? "disabled" : ""}>Dump</button>

            <button type="button" class="btn btn-default btn-sm pts1-btn"
              data-action="FLASH" data-lane="${lane}" ${busy ? "disabled" : ""}>Flash</button>

            <button type="button" class="btn btn-default btn-sm pts1-btn"
              data-action="UPLOAD" data-lane="${lane}" ${uploadEnabled ? "" : "disabled"}>Upload</button>

            <button type="button" class="btn btn-default btn-sm pts1-btn"
              data-action="RESET" data-lane="${lane}" ${busy ? "disabled" : ""}>Reset</button>
          </div>
        </div>
      `);

      $rows.append($laneRow);
    }

    // single click binding
    $root.off("click.pts1");
    $root.on("click.pts1", ".pts1-btn", function () {
      const lane_no = Number($(this).attr("data-lane"));
      const action = $(this).attr("data-action");

      console.log("[PTS1] CLICK", { lane_no, action });

      if (action === "UPLOAD") return upload_lane_result(frm, lane_no);
      if (action === "RESET") return reset_lane(frm, lane_no);
      return request_action(frm, lane_no, action);
    });
  }

  // -----------------------
  // Logs -> optional view fields
  // -----------------------
  function sync_lane_logs_to_fields(frm) {
    const map = { 1: "lane1_log_view", 2: "lane2_log_view", 3: "lane3_log_view", 4: "lane4_log_view" };

    for (let lane = 1; lane <= 4; lane++) {
      const row = lane_row(frm, lane);
      const fieldname = map[lane];
      if (!frm.fields_dict[fieldname]) continue;

      const val = row?.lane_log ? row.lane_log : "";
      if ((frm.doc[fieldname] || "") !== val) frm.set_value(fieldname, val);
    }
  }

  // -----------------------
  // Auto refresh while running/requested
  // -----------------------
  function start_auto_refresh_if_needed(frm) {
    const shouldRun = anyLaneActive(frm);

    if (shouldRun && !frm.__lane_timer) {
      frm.__lane_timer = setInterval(() => {
        if (!anyLaneActive(frm)) {
          clearInterval(frm.__lane_timer);
          frm.__lane_timer = null;
          return;
        }
        frm.reload_doc();
      }, 900);
    }

    if (!shouldRun && frm.__lane_timer) {
      clearInterval(frm.__lane_timer);
      frm.__lane_timer = null;
    }
  }

  // -----------------------
  // CSS
  // -----------------------
  function inject_pts1_css_once() {
    if (document.getElementById("pts1-dash-css")) return;

    const css = `
      .pts1-dash { padding: 8px 0; }
      .pts1-row {
        display: grid;
        grid-template-columns: 40px 1fr 360px;
        gap: 10px;
        align-items: center;
        margin: 10px 0;
      }
      .pts1-label { font-weight: 700; opacity: 0.95; }
      .pts1-bar {
        position: relative;
        height: 18px;
        border-radius: 10px;
        background: rgba(255,255,255,0.10);
        overflow: hidden;
      }
      .pts1-barfill { height: 100%; }
      .pts1-barfill-pending { background: rgba(255,255,255,0.18); }
      .pts1-barfill-queued { background: rgba(255,200,90,0.55); }
      .pts1-barfill-running { background: rgba(90, 180, 255, 0.55); }
      .pts1-barfill-done { background: rgba(120, 220, 150, 0.55); }
      .pts1-barfill-failed { background: rgba(255, 90, 90, 0.65); }
      .pts1-barfill-aborted { background: rgba(255, 140, 0, 0.65); }

      .pts1-bartext {
        position: absolute;
        inset: 0;
        display: flex;
        align-items: center;
        justify-content: flex-end;
        padding-right: 8px;
        font-size: 12px;
        opacity: 0.9;
        pointer-events: none;
        white-space: nowrap;
      }
      .pts1-actions {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 10px;
      }
      .pts1-actions .btn {
        width: 100%;
        min-width: 0;
        padding: 7px 10px;
        font-weight: 600;
        border-radius: 10px;
        white-space: nowrap;
      }
      .pts1-actions .btn[disabled] { opacity: 0.55; cursor: not-allowed; }
    `;

    const style = document.createElement("style");
    style.id = "pts1-dash-css";
    style.innerHTML = css;
    document.head.appendChild(style);
  }
})();

